<?php
namespace App\Models;
use App\Models\Concerns\BelongsToTenant; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes;
class AcademicBill extends Model { use SoftDeletes,BelongsToTenant; protected $guarded=[]; protected $casts=['issued_at'=>'date','due_date'=>'date','subtotal'=>'decimal:2','discount'=>'decimal:2','penalty'=>'decimal:2','total'=>'decimal:2','paid_amount'=>'decimal:2','metadata'=>'array']; public function student(){return $this->belongsTo(Student::class);} public function semester(){return $this->belongsTo(Semester::class);} public function feeType(){return $this->belongsTo(FeeType::class);} public function payments(){return $this->hasMany(Payment::class);} public function getOutstandingAmountAttribute(){return max(0,(float)$this->total-(float)$this->paid_amount);} }
